L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "La langue d'affichage du panneau d'options d'EllesmereUI. Auto suit votre client de jeu. Le texte non traduit revient à l'anglais."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "La couleur de remplissage unie utilisée par les barres quand le mode sombre est activé (cadres d'unité, cadres de raid, barres de ressource)."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Ces réglages privilégient la fluidité et la clarté visuelle par rapport au détail de l'environnement. Les textures restent de haute qualité pour que votre personnage et le monde restent parfaits."
