L["This feature requires Snap Elements to be enabled"] = "Cette fonction nécessite que l'aimantation des éléments soit activée"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Ceci est la fenêtre de file d'attente des sorts ; elle aide à éviter de mettre en file trop de sorts à la fois, ce qui donne une impression de latence. Les réglages recommandés sont généralement d'au moins 200 + votre ping local. Si vous n'êtes pas sûr de ce que fait ce réglage, laissez-le à 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "C'est ici que vous contrôlez les réglages du mode Déverrouillage.\n\nLes éléments peuvent être repositionnés par glisser ou avec les touches fléchées (+Maj)\nAncrez, alignez la hauteur ou la largeur de n'importe quel élément.\nL'aimantation se base sur l'élément le plus proche, mais vous pouvez aimanter à\n un élément spécifique via le clic droit ou l'icône de réglages."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Fait en sorte que la largeur de la barre d'incantation inclue l'icône, au lieu de la placer à gauche de la largeur des barres d'incantation."
