L["Blizzard's aura borders on the buffs, debuffs and weapon enchants, with every EllesmereUI bar feature."] = "Les bordures d'aura de Blizzard sur les améliorations, affaiblissements et enchantements d'arme, avec toutes les fonctions de barre EllesmereUI."
L["Blizzard's bar panel and action button frame, or the classic bar frame and slot ring, with every EllesmereUI Skyriding HUD feature."] = "Le panneau de barre et le cadre des boutons d'action de Blizzard, ou le cadre de barre et l'anneau d'emplacement classiques, avec toutes les fonctions du HUD Vol dynamique EllesmereUI."
L["Blizzard's buff bar art, or the classic cast bar frame, with every EllesmereUI tracked bar feature."] = "L'illustration de barre d'amélioration de Blizzard, ou le cadre de barre d'incantation classique, avec toutes les fonctions de barre suivie EllesmereUI."
L["Blizzard's cast bar art, or the classic cast bar frame, with every EllesmereUI cast bar feature."] = "L'illustration de barre d'incantation de Blizzard, ou le cadre de barre d'incantation classique, avec toutes les fonctions de barre d'incantation EllesmereUI."
L["Blizzard's frame art, portraits and bar shapes, or the classic frames, with every EllesmereUI frame feature."] = "Les illustrations de cadre, portraits et formes de barre de Blizzard, ou les cadres classiques, avec toutes les fonctions de cadre EllesmereUI."
L["Blizzard's health and cast bar art, or the classic flat plates, with every EllesmereUI nameplate feature."] = "Les illustrations de barre de vie et d'incantation de Blizzard, ou les plaques plates classiques, avec toutes les fonctions de barres d'info EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI meter feature."] = "La fenêtre de compteur et les barres de Blizzard, ou une fenêtre dans la bordure des onglets de discussion classiques, avec toutes les fonctions de compteur EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI threat meter feature."] = "La fenêtre de compteur et les barres de Blizzard, ou une fenêtre dans la bordure des onglets de discussion classiques, avec toutes les fonctions de compteur de menace EllesmereUI."
L["Blizzard's own character sheet as the game draws it; WoW Forever keeps the item text beside the slots, and the stat colors stay with the EllesmereUI look."] = "La fiche de personnage de Blizzard telle que le jeu l'affiche ; WoW Forever garde le texte des objets à côté des emplacements, et les couleurs des statistiques restent au style EllesmereUI."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "La fiche de personnage de Blizzard avec les statistiques, le texte d'emplacement et le panneau de châsses EllesmereUI ajoutés ; l'onglet Calc reste au style EllesmereUI."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "La fenêtre de discussion, les onglets et la zone de saisie de Blizzard, ou la même fenêtre avec les onglets classiques, avec toutes les fonctions de discussion EllesmereUI."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "Les illustrations de cadre et de bouton de Blizzard, avec les fonctions d'EllesmereUI."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "La fenêtre d'amis et les cartes de Blizzard, avec les icônes de classe, les noms colorés par classe et les icônes de région EllesmereUI ajoutés. Les deux styles d'origine sont identiques ici."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "Le suivi de Blizzard, avec toutes les fonctions de suivi EllesmereUI. Les deux styles d'origine sont identiques ici."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "Les bords et surbrillances des cadres de raid de Blizzard, ou les classiques, avec toutes les fonctions de cadres de raid EllesmereUI."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "La minicarte ronde et l'en-tête de Blizzard, ou l'anneau classique, avec toutes les fonctions de minicarte EllesmereUI."
