L["Shows every debuff on this frame."] = "Affiche tous les affaiblissements sur ce cadre."
L["Shows incoming heals past the health bar: yours, then other players'."] = "Affiche les soins entrants au-delà de la barre de vie : les vôtres, puis ceux des autres joueurs."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Affiche les grands montants avec les suffixes K/M (284,208g devient 284.2Kg) au lieu du nombre complet. L'infobulle affiche toujours le montant exact."
L["Shows only debuffs Blizzard flags as important."] = "Affiche uniquement les affaiblissements que Blizzard marque comme importants."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Affiche uniquement les affaiblissements correspondant à tous les filtres Afficher cochés (les types de dissipation comptent pour un) ; des opposés comme Auras non-joueur avec Lancé par vous n'affichent rien."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Affiche uniquement les affaiblissements que vous appliquez et que Blizzard marque aussi comme importants."
L["Shows only the debuffs you apply."] = "Affiche uniquement les affaiblissements que vous appliquez."
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Affiche uniquement les auras suivies de ce cadre ; ajoutez-les avec Modifier les auras suivies en haut de ce menu."
L["Shows the audio icon next to the volume bar."] = "Affiche l'icône audio à côté de la barre de volume."
L["Shows the bag icon next to the slot count."] = "Affiche l'icône de sac à côté du nombre d'emplacements."
L["Shows the combat status text only while your character is in combat."] = "Affiche le texte de statut de combat uniquement quand votre personnage est en combat."
L["Shows the cost of the spell being cast on the power bar."] = "Affiche le coût du sort en cours d'incantation sur la barre de ressource."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Affiche la description de la monnaie dans l'infobulle. Désactivez pour une infobulle compacte avec seulement le nom et le montant."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Affiche les affaiblissements que vous appliquez plus les affaiblissements importants de n'importe qui."
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Affiche le cadre quand cette unité n'a pas toute sa vie ; une fois activé, un cadre masqué par son réglage de visibilité reste cliquable."
L["Shows the health text elements placed in Core Text Positions."] = "Affiche les éléments de texte de vie placés dans Positions du texte principal."
L["Shows the last lines of each chat window again after a reload or relog."] = "Réaffiche les dernières lignes de chaque fenêtre de chat après un rechargement ou une reconnexion."
L["Shows the most important boss debuff (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) as a large icon in the middle of the frame."] = "Affiche l'affaiblissement de boss le plus important (ICC, Sanctum rubis, ToC, Ulduar, Naxxramas) sous forme de grande icône au centre du cadre."
L["Shows the network latency zone at the end of casts or channels, including queued spells."] = "Affiche la zone de latence réseau à la fin des incantations ou canalisations, sorts en file inclus."
L["Shows the overlay only for debuffs you can currently dispel."] = "Affiche la superposition uniquement pour les affaiblissements que vous pouvez dissiper actuellement."
L["Shows the plugin's own icon next to its text."] = "Affiche l'icône propre du plugin à côté de son texte."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Affiche le texte du plugin. Désactivé laisse un bloc icône seule qui conserve l'infobulle et les clics du plugin."
L["Shows the profession icons next to the text."] = "Affiche les icônes de métier à côté du texte."
L["Shows the spec icon next to the text."] = "Affiche l'icône de spécialisation à côté du texte."
