L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Ce qui se trouve devant le nombre. Icône affiche l'icône du personnage ; les nuances de couleur à gauche la teintent."
L["When Healing uses your role or healing talents"] = "Quand Soins utilise votre rôle ou vos talents de soins"
L["When on, flask/food/weapon/poison reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Si activé, les rappels de flacon/nourriture/arme/poison s'affichent quand même (atténués) si vous n'avez pas l'objet correspondant dans vos sacs, pour vous inciter à vous réapprovisionner.\nSi désactivé, ils sont entièrement masqués si vous ne portez pas l'objet."
L["When unlocked, hold Shift and drag the minimap. Position is also available in Unlock Mode."] = "Une fois déverrouillée, maintenez Shift et faites glisser la minicarte. La position est aussi disponible dans le Mode Déverrouillage."
L["Where to Show"] = "Où afficher"
L["Which audio channel the block's volume bar adjusts."] = "Le canal audio que règle la barre de volume du bloc."
L["Which latency to show: home, world, or both side by side."] = "Latence à afficher : domicile, monde, ou les deux côte à côte."
L["Which part of the row stays in place as reminders appear and disappear."] = "La partie de la rangée qui reste en place quand les rappels apparaissent et disparaissent."
L["Which sections the gold tooltip shows."] = "Les sections affichées par l'infobulle d'or."
L["Which slot count the block shows."] = "Le décompte d'emplacements affiché par le bloc."
L["Which view the bags open to by default."] = "La vue ouverte par défaut par les sacs."
L["While Group by Category is on, drop the trailing block of empty slots so the view only shows items."] = "Quand Grouper par catégorie est actif, retire le bloc final d'emplacements vides pour n'afficher que les objets."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Sur une monture capable de planer, y compris au sol, là où Blizzard affiche son ATH de vigueur. Chevauchée céleste (en vol) exige en plus que vous voliez."
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "Pendant que le Mode Groupe est actif. Le Mode Groupe peut démarrer en combat (Furie sanguinaire) ; les éléments sécurisés comme les barres d'action gardent alors leur visibilité actuelle jusqu'à la fin du combat."
L["While resting, in a city or at an inn."] = "Au repos, en ville ou dans une auberge."
L["While seated in a vehicle."] = "Assis dans un véhicule."
L["While you are inside a house or plot."] = "Lorsque vous êtes dans une maison ou un terrain."
L["While you cast, shows on the bar the mana the spell will cost."] = "Pendant une incantation, affiche sur la barre le mana que coûtera le sort."
