L["Wrath only has a Blizzard class resource bar for Death Knight runes."] = "Wrath n'a une barre de ressource de classe Blizzard que pour les runes du chevalier de la mort."
L["Wrath raid and party frames with native unit clicks, auras, range and click casting."] = "Cadres de raid et de groupe Wrath avec clics d'unité natifs, auras, portée et soins au clic."
L["Wrath spells, items and auras. Assignments are saved for each dual talent group."] = "Sorts, objets et auras Wrath. Les attributions sont enregistrées pour chaque groupe de talents."
L["Wrath's native quest and achievement tracker with EUI styling, visibility rules, auto-accept/turn-in and a quest-item hotkey."] = "Suivi natif des quêtes et hauts faits de Wrath avec style EUI, règles de visibilité, acceptation/rendu auto et raccourci d'objet de quête."
L["XP & Reputation Text Size"] = "Taille du texte XP et réputation"
