L["You are displaying NO debuffs at all."] = "Vous n'affichez AUCUN affaiblissement."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Vous avez modifié la valeur par défaut d'un réglage qui a des remplacements. Les remplacements gardent leurs propres valeurs, ce changement n'atteindra donc pas les spécialisations ou conditions qu'ils couvrent. Pour le modifier dans un remplacement, choisissez-le via le glyphe de classe à côté de la barre de recherche du module et modifiez-le là."
L["You don't have this item in your bags"] = "Vous n'avez pas cet objet dans vos sacs"
L["You have not learned %1$s."] = "Vous n'avez pas appris %1$s."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "Votre spécialisation actuelle a son propre gestionnaire d'affaiblissements personnalisé, les gestionnaires conditionnels ne s'y appliquent donc jamais."
L["Your heals"] = "Vos soins"
L["Your preferred food is out - using a backup you own"] = "Votre nourriture préférée est épuisée - utilisation d'une alternative que vous possédez"
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "Votre configuration et toutes les fonctionnalités d'EllesmereUI sont conservées ; seule l'apparence change. Appliquez un style à tous les modules en un clic, ou réglez chaque module ci-dessous. Changer de style recharge l'UI."
L["Your UI, Restyled in Seconds"] = "Votre UI, relookée en quelques secondes"
